Parse the agent-category and agent-schedule tables from the active sheet. For each answer category row and interval column, sum schedule values multiplied by the corresponding category flags over all agents. Write the resulting plain numbers into F22:AE29.

```python
import shutil
import openpyxl
import re
import datetime

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

answer_ws = wb.active
vws = vals[answer_ws.title]

def norm(x):
    if x is None:
        return None
    if isinstance(x, str):
        s = x.strip()
        return s if s else None
    return x

def is_time_like(x):
    if x is None:
        return False
    if isinstance(x, (datetime.datetime, datetime.time)):
        return True
    if isinstance(x, float) and 0 <= x < 1:
        return True
    s = str(x).strip()
    return bool(re.match(r"^\d{1,2}:\d{2}(:\d{2})?$", s))

def to_num(x):
    if x is None:
        return 0.0
    if isinstance(x, bool):
        return 1.0 if x else 0.0
    try:
        return float(x)
    except Exception:
        return 0.0

# Locate Agent Categories header (first "Category 1")
cat_header_row = None
cat_header_col = None
for row in vws.iter_rows():
    for cell in row:
        if norm(cell.value) == "Category 1":
            cat_header_row = cell.row
            cat_header_col = cell.column
            break
    if cat_header_row is not None:
        break

if cat_header_row is None:
    cat_header_row, cat_header_col = 3, 6

cat_agent_col = cat_header_col - 1
cat_cols = {}
for c in range(cat_header_col, vws.max_column + 1):
    name = norm(vws.cell(cat_header_row, c).value)
    if name and str(name).startswith("Category"):
        cat_cols[str(name)] = c

agent_cat = {}
r = cat_header_row + 1
while r <= vws.max_row:
    agent = norm(vws.cell(r, cat_agent_col).value)
    if agent is None:
        break
    agent = str(agent)
    cats = {}
    for name, c in cat_cols.items():
        num = to_num(vws.cell(r, c).value)
        if num:
            cats[name] = num
    agent_cat[agent] = cats
    r += 1

# Locate Agent Schedule header ("Agent" followed by a time-like header)
sched_header_row = None
sched_agent_col = None
for row in vws.iter_rows():
    for cell in row:
        if norm(cell.value) == "Agent" and cell.column < vws.max_column:
            next_val = norm(vws.cell(cell.row, cell.column + 1).value)
            if is_time_like(next_val):
                sched_header_row = cell.row
                sched_agent_col = cell.column
                break
    if sched_header_row is not None:
        break

if sched_header_row is None:
    agent_headers = []
    for row in vws.iter_rows():
        for cell in row:
            if norm(cell.value) == "Agent":
                agent_headers.append((cell.row, cell.column))
    if len(agent_headers) >= 2:
        sched_header_row, sched_agent_col = agent_headers[1]
    else:
        sched_header_row, sched_agent_col = 12, 5

sched_cols = []
c = sched_agent_col + 1
while c <= vws.max_column:
    h = norm(vws.cell(sched_header_row, c).value)
    if h is None:
        break
    sched_cols.append(c)
    c += 1

schedule = {}
r = sched_header_row + 1
while r <= vws.max_row:
    agent = norm(vws.cell(r, sched_agent_col).value)
    if agent is None:
        break
    agent = str(agent)
    row_vals = {}
    for c in sched_cols:
        num = to_num(vws.cell(r, c).value)
        if num:
            row_vals[c] = num
    schedule[agent] = row_vals
    r += 1

# Fill answer region F22:AE29
for r in range(22, 30):
    cat_name = norm(vws.cell(r, 5).value)
    cat_name = str(cat_name) if cat_name is not None else None
    for c in range(6, 32):
        total = 0.0
        if cat_name is not None:
            for agent, row_vals in schedule.items():
                cat_val = agent_cat.get(agent, {}).get(cat_name, 0.0)
                if cat_val:
                    total += row_vals.get(c, 0.0) * cat_val
        if abs(total - round(total)) < 1e-9:
            total = int(round(total))
        answer_ws.cell(r, c).value = total

wb.save(OUT)

print("agent_cat rows:", len(agent_cat))
print("schedule rows:", len(schedule))
print("schedule cols:", len(sched_cols))
print("Category 1 first 6:", [answer_ws.cell(22, c).value for c in range(6, 12)])
print("Category 8 last 6:", [answer_ws.cell(29, c).value for c in range(26, 32)])
